def rob(nums: list[int]) -> int:
    def line(lo: int, hi: int) -> int:
        skip = take = 0
        for i in range(lo, hi):
            skip, take = max(skip, take), skip + nums[i]
        return max(skip, take)

    n = len(nums)
    return nums[0] if n == 1 else max(line(0, n - 1), line(1, n))
